  "privRights": "Els teus drets",
  "noticeReopen": "Avís d’emmagatzematge",
  "noticeLabel": "Avís d’emmagatzematge del navegador",
  "noticeText": "Cook fa servir l’emmagatzematge del navegador per a les funcions de cuina i d’inici de sessió que utilitzes. No s’afegeix cap emmagatzematge publicitari ni analític.",
  "noticeClose": "Tanca l’avís d’emmagatzematge",
  "privDraftLabel": "Esborrany — actualitzat el 28 d’octubre de 2026.",
  "privDraft": "Les funcions de compte s’estan provant. Les dades del responsable i dels serveis que hi ha a continuació s’han de completar abans del llançament públic.",
  "privWho1": "Cook és gestionat per [nom legal i adreça postal del responsable]. Escriu a [adreça de correu de privadesa] per a consultes i sol·licituds sobre privadesa. Aquestes dades s’han de completar abans d’obrir el registre.",
  "privWhat1": "Quan crees un compte, fem servir el teu correu, un identificador de compte, els registres d’autenticació amb contrasenya i l’estat de verificació per oferir i protegir el teu compte. El proveïdor d’autenticació tracta les contrasenyes com a hashes segurs; Cook no desa contrasenyes llegibles. Desem la distribució de la cuina, l’idioma triat, el tema i les unitats de mesura per restaurar la configuració a tots els dispositius. Per tenir compte cal un correu i una contrasenya; pots consultar receptes sense compte.",
  "privWhat2": "El tractament del compte i de la configuració és necessari per prestar el servei de compte que demanes (article 6.1.b del RGPD). Es poden tractar registres limitats de seguretat i prevenció d’abusos per interès legítim (article 6.1.f), sempre que sigui necessari i després de la ponderació corresponent. Els correus de verificació i de restabliment de contrasenya són missatges de servei, no publicitat. La funció de compte no afegeix publicitat ni analítica.",
  "privStorage1": "Cook fa servir sessionStorage per portar la cuina, el progrés de la recepta i les teves opcions entre pàgines de la mateixa pestanya. Si has iniciat la sessió, també hi desa la sessió d’autenticació. El navegador normalment ho esborra quan acaba la sessió de la pestanya, però la restauració de sessions del navegador ho pot conservar. En tancar la sessió s’esborren les dades de pestanya de Cook. El tancament de l’avís d’emmagatzematge només es desa en aquella pestanya. Els scripts propis de Cook no creen galetes. Els teus proveïdors d’allotjament o de serveis poden fer tractaments de seguretat propis, que s’han de documentar abans del llançament.",
  "privStorage2": "D’acord i el botó de tancar de l’avís d’emmagatzematge només tanquen l’avís. No autoritzen analítica, publicitat ni cap altre seguiment opcional. Qualsevol emmagatzematge no essencial futur requerirà una elecció separada abans de començar, amb un rebuig i una retirada igual de fàcils.",
  "privOther1": "La funció de veu actual de la llista de receptes demana a country.is un país aproximat a partir de la teva adreça IP per triar l’idioma de veu. Si fas servir el reconeixement pel micròfon, el navegador pot enviar l’àudio al seu proveïdor de reconeixement de veu. També pots escriure els ingredients. Aquests proveïdors, les seves polítiques i la base jurídica d’aquestes funcions s’han de revisar abans del llançament públic.",
  "privProviders1": "Proveïdor de comptes previst: Supabase (PostgreSQL i autenticació gestionats), amb una regió de base de dades triada a la UE. Proveïdor de correu: [proveïdor]. Allotjament web: [proveïdor]. El responsable ha de confirmar els proveïdors reals, els contractes d’encàrrec del tractament, els subencarregats, la ubicació dels registres i qualsevol transferència fora de l’EEE. Una regió de base de dades a la UE no exclou per si sola les transferències internacionals. Quan escaigui, cal indicar la decisió d’adequació o les garanties contractuals aplicables i com obtenir-ne una còpia.",
  "privRetention1": "La configuració del compte es conserva mentre el compte estigui actiu. Pots demanar-ne la supressió mitjançant el contacte de privadesa indicat més amunt. Abans del llançament, el responsable ha d’especificar el procediment de resposta a les sol·licituds de supressió, la caducitat dels comptes no verificats i els terminis de conservació dels registres de seguretat i de les còpies de seguretat. Les dades suprimides poden romandre en còpies de seguretat d’accés restringit fins que acabi el termini de conservació documentat.",
  "privRights1": "Segons les condicions aplicables, pots sol·licitar l’accés, la rectificació, la supressió, la limitació o la portabilitat, o oposar-te al tractament basat en l’interès legítim. Contacta amb el responsable indicat més amunt; normalment les sol·licituds es responen en un mes i s’explica qualsevol pròrroga legal. Pots presentar una reclamació davant la teva autoritat de control, inclosa la NAIH d’Hongria a naih.hu. Cook no fa servir la configuració del compte per a decisions automatitzades amb efectes jurídics o efectes igualment significatius.",
